async def migrate_branding():
    db = await get_db()
    try:
        for table, columns in {
            "guild_settings": ["value"],
            "ticket_panels": ["embed_title", "embed_desc"],
            "application_templates": ["panel_title", "panel_description", "submission_title"],
            "welcome_config": ["message", "goodbye_message"],
        }.items():
            async with db.execute(f'PRAGMA table_info("{table}")') as cursor:
                available = {row[1] for row in await cursor.fetchall()}
            for column in columns:
                if column not in available:
                    continue
                for old, new in REPLACEMENTS:
                    await db.execute(f'UPDATE "{table}" SET "{column}"=? WHERE "{column}"=?', (new, old))
                for old, new in [("BLISS AU", "AU SCHOOLS"), ("Bliss AU", "AU Schools"), ("Pacific FFA", "AU Schools")]:
                    await db.execute(f'UPDATE "{table}" SET "{column}"=replace("{column}", ?, ?) WHERE instr("{column}", ?) > 0', (old, new, old))
        await db.commit()
    finally:
        await db.close()
